def premiers(n):
    """Renvoie la liste des nombres premiers strictement inférieurs à n."""
    result = []
    for i in range(2, n):
        is_prime = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            result.append(i)
    return result
```

